// TRACK B owns this file. C9 pre-visit brief, generated by the Elastic Workflow.
// internal.briefs.save is called by elastic.generateBrief (Workflow result or fallback).
import { v, type Infer } from "convex/values";
import { internalMutation, query } from "./_generated/server";

const source = v.union(v.literal("elastic_workflow"), v.literal("fallback"), v.literal("seed"));

// H8: overview, reported concerns and topics for review, each item citing the patient's words.
export const briefItem = v.object({
  text: v.string(),
  citations: v.array(
    v.object({
      symptomEntryId: v.optional(v.string()),
      date: v.string(),
      quoteOriginal: v.string(),
      quoteEnglish: v.string(),
    }),
  ),
});
export const briefSections = v.object({
  overview: v.string(),
  concerns: v.array(briefItem),
  topics: v.array(briefItem),
});

const briefDoc = v.object({
  _id: v.id("briefs"),
  _creationTime: v.number(),
  patientId: v.id("patients"),
  appointmentId: v.id("appointments"),
  textEnglish: v.string(),
  createdAt: v.number(),
  source,
  sections: v.optional(briefSections), // Schema v2, written from block B5
});
const maybeBrief = v.union(v.null(), briefDoc);

/** Doctor patient view brief card: the newest brief for this appointment. */
export const getByAppointment = query({
  args: { appointmentId: v.id("appointments") },
  returns: maybeBrief,
  handler: async (ctx, args): Promise<Infer<typeof maybeBrief>> => {
    return await ctx.db
      .query("briefs")
      .withIndex("by_appointment", (q) => q.eq("appointmentId", args.appointmentId))
      .order("desc")
      .first();
  },
});

/** elastic.generateBrief writes here. */
export const save = internalMutation({
  args: {
    patientId: v.id("patients"),
    appointmentId: v.id("appointments"),
    textEnglish: v.string(),
    source,
    sections: v.optional(briefSections),
  },
  returns: v.id("briefs"),
  handler: async (ctx, args) => {
    return await ctx.db.insert("briefs", { ...args, createdAt: Date.now() });
  },
});
